/* =============================================================================
   08_lecturas_latam.sql -- lecturas mensuales 2026 de los paises LATAM nuevos
   (Mexico, Argentina, Chile, Costa Rica, Nicaragua, Guatemala, Honduras,
   Ecuador, Republica Dominicana, Brasil). NO toca Celta/Estrella/Agencias/
   Peru/Colombia/Colombia+Peru -- esos los gobierna el pipeline propio de
   ehs/CLAUDE.md, con correcciones ya validadas por el area. EUA no trae 2026
   en el Excel (solo historico 2019-2023): sigue sin dato.

   Fuente: Excel "EHS BD LATAM (3).xlsx", hojas por pais -- entregado por
   Samuel el 17-nov-2026. Llena huecos de meses anteriores (ej. Brasil marzo)
   y agrega octubre; idempotente (insert ... on conflict ... do update), se
   puede re-correr sin duplicar.

   6 sitios nuevos que el Excel trae con dato real y 06_paises_latam.sql no
   tenia todavia: 3 agencias ya anticipadas en src/validacion.js (chile_megalux_ag,
   honduras_popular_ag, brasil_unilab_ag) + 3 descubiertos en esta carga
   (ecuador_quito_versalles, brasil_duque_caxias, brasil_sumare). Ciudad en null
   donde no se pudo verificar -- no se inventa (R.5 de EssilorLuxottica/CLAUDE.md).
   ============================================================================= */

begin;

insert into ref.dim_sitio
    (sitio_id, sitio, sitio_corto, nombre_corporativo, tipo, ciudad,
     en_nacional_labs, en_nacional, en_colombia_peru, activo) values
    ('chile_megalux_ag', 'Agencias Megalux Chile', 'Agencias Megalux', 'Agencias Megalux Chile', 'Agencia', null, false, false, false, true),
    ('honduras_popular_ag', 'Agencias Optica Popular Honduras', 'Agencias Opt. Popular', 'Agencias Optica Popular Honduras', 'Agencia', null, false, false, false, true),
    ('brasil_unilab_ag', 'Agencias Unilab Fortaleza', 'Agencias Unilab', 'Agencias Unilab Fortaleza', 'Agencia', 'Fortaleza', false, false, false, true),
    ('ecuador_quito_versalles', 'Indulentes Quito Versalles', 'Indulentes Versalles', 'Indulentes Quito Versalles', 'Laboratorio', 'Quito', false, false, false, true),
    ('brasil_duque_caxias', 'Multioptica Duque de Caxias', 'Multioptica Duque Caxias', 'Multioptica Duque de Caxias', 'Agencia', 'Duque de Caxias', false, false, false, true),
    ('brasil_sumare', 'Lab Sumare', 'Lab Sumare', 'Lab Sumare', 'Laboratorio', 'Sumare', false, false, false, true)
on conflict (sitio_id) do update set
    sitio = excluded.sitio, sitio_corto = excluded.sitio_corto,
    nombre_corporativo = excluded.nombre_corporativo, ciudad = excluded.ciudad;

insert into ref.bridge_ambito_sitio (ambito_id, sitio_id) values
    ('chile', 'chile_megalux_ag'),
    ('latam', 'chile_megalux_ag'),
    ('honduras', 'honduras_popular_ag'),
    ('latam', 'honduras_popular_ag'),
    ('brasil', 'brasil_unilab_ag'),
    ('latam', 'brasil_unilab_ag'),
    ('ecuador', 'ecuador_quito_versalles'),
    ('latam', 'ecuador_quito_versalles'),
    ('brasil', 'brasil_duque_caxias'),
    ('latam', 'brasil_duque_caxias'),
    ('brasil', 'brasil_sumare'),
    ('latam', 'brasil_sumare')
on conflict (ambito_id, sitio_id) do nothing;

